                    const radius = 65;

                    const theta =
                    Math.random() *
                    Math.PI *
                    2;

                    const phi =
                    Math.random() *
                    Math.PI *
                    .45;


                    star.position.set(
                    radius *
                    Math.sin(phi) *
                    Math.cos(theta),

                    radius *
                    Math.cos(phi),

                    radius *
                    Math.sin(phi) *
                    Math.sin(theta)
                    );


                    star.userData.twinkleSpeed =
                    .5 +
                    Math.random() * 2.5;

                    star.userData.twinklePhase =
                    Math.random() *
                    Math.PI *
                    2;


                    stars.push(star);

                    starGroup.add(star);
